    "eigenvalues_of_square_matrix": "Bir kare matrisin özdeğerleri, gerçel ya da a ± bi, karakteristik polinomu ve izi, ve her gerçel özdeğerin özvektörleri: A'nın yalnızca λ kadar uzattığı v. Boyutunu yazın, 3×3 veya 3, en çok 10×10, ve her kutuya bir sayı girin ya da bir kutuya bütün matrisi yapıştırın, bir hesap tablosundan veya [1 2; 3 4] biçiminde; boş kutu 0'dır.",
