    "555_timer_astable_blinking": "Kendi kendine yanıp sönen kararsız (astable) modda 555 zamanlayıcı, R<sub>1</sub>, R<sub>2</sub> ve C ile: frekansı, yüksek ve düşük süreleri ve doluluk oranı; ya da tek kararlı (monostable) modda, tek darbe, R ve C ile: ne kadar sürdüğü.",
