    "level_in_dbm_dbw": "dBm, dBW, watt, dBV, dBmV, dBµV ya da RMS volt cinsinden bir seviyenin diğerlerinin her birinde karşılığı, bir Z empedansı üzerinde: radyoda 50 Ω, video ve TV'de 75, eski seste 600; tepe ve tepeden tepeye gerilimi ve akımla. Sinyal seviyeleri arasında çizilir. Ya da bir kazanç veya kayıp: güç ve gerilim oranı olarak dB, ya da dB olarak bir oran.",
