    "steady_acceleration": "Sabit ivme",
    "motion_in_line_at": "Sabit ivmeli doğrusal hareket: s, alınan yol, u, ilk hız, v, son hız, a, ivme ve t, süreden herhangi üçünü yazın, diğer ikisi hesaplanır. Karesinden bulunan bir hız iki yönde de olabilir: ikisi de verilir.",
    "projectile": "Eğik atış",
    "something_thrown_at_speed": "Bir yükseklikten, yerden bir açı ve hızla havasız ortamda fırlatılan cisim: ne kadar uçtuğu, ne kadar uzağa, ne kadar yükseğe gittiği ve hangi hızla yere düştüğü; yolu çizilir. Açı kullanılan birimde.",
    "relative_velocity": "Bağıl hız",
    "two_things_moving_each": "Her biri bir hız ve yönle hareket eden iki cisim: birinin diğerinden bakıldığında ne hızla ve hangi yöne gittiği, çizimli. Ya da d genişliğinde, akıntısı u olan bir nehri suya göre v hızıyla geçen bir tekne: tam karşıya yönelirse ne kadar sürdüğü ve ne kadar aşağıda karaya çıktığı; ve onu tam karşıya götüren akıntıya karşı yön. Yönler doğudan, saat yönünün tersine, kullanılan birimde.",
