    "circular_motion": "Dairesel hareket",
    "going_round_circle_of": "r yarıçaplı bir çemberde sabit hızla dönme, hızı, periyodu veya dakikadaki devir sayısından: diğer ikisi, açısal hız ve frekans, merkezcil ivme ve bir kütle için onu tutan kuvvet.",
    "speed": "Hız",
    "period_2": "Periyot",
    "kg_optional": "kg, isteğe bağlı",
    "orbits": "Yörüngeler",
    "satellite_or_planet_going": "M kütleli ve R yarıçaplı bir cismin etrafında dönen uydu veya gezegen, Kepler'in üçüncü yasasıyla: yüzeyden yüksekliğinden, periyodundan ya da en yakın ve en uzak yüksekliklerinden, bir elips: yörüngesinin boyutu, periyodu ve hızı, vis-viva denklemiyle en yakında ve en uzakta; çizimli. Yazılmazsa Dünya, 5.972e24 kg ve 6.371e6 m; Güneş 1.989e30 kg ve 6.957e8 m. Yerdurağan yörünge 86164 s sürer.",
