    "farthest": "En uzak",
    "rocket_equation": "Roket denklemi",
    "tsiolkovsky_s_speed_rocket": "Tsiolkovsky: bir roketin yakıtını yakarak kazandığı hız, egzoz hızı v<sub>e</sub> ya da özgül itkisi I<sub>sp</sub>, dolu kütlesi m<sub>0</sub> ve boş kütlesi m<sub>f</sub> ile; yanarken hızı çizilir. Yanma süresiyle itkisi, başta ve sonda ivmesi ve g'ye karşı dikey yükselirken kalan Δv. Kerosen motorunun I<sub>sp</sub>'si yaklaşık 300 s, hidrojenlinin 450; yörüngeye çıkmak yaklaşık 9400 m/s gerektirir.",
