    "inclined_plane": "Eğik düzlem",
    "mass_on_slope_of": "Sürtünmesi μ olan θ açılı bir eğimdeki kütle: ağırlığı, normal kuvvet, eğim boyunca kuvvet, sürtünme ve ivme, ve kayıp kaymadığı.",
    "masses_over_pulley": "Makara üzerinden kütleler",
    "two_masses_on_string": "Bir makara üzerinden geçen ipe bağlı iki kütle, m<sub>1</sub> asılı ve m<sub>2</sub> de asılı, Atwood makinesi gibi, masada ya da θ açılı bir eğimde, sürtünme μ ile: ivmeleri, hangi yöne gittikleri, ipteki gerilme ve sürtünmenin onları tutup tutmadığı; çizimli. Bir d mesafesiyle, sonunda ne hızla gittikleri ve ne kadar sürdüğü. Makaranın kütlesiyle, disk olarak, o da döner.",
