    "torque_and_levers": "Tork ve kaldıraçlar",
    "turning_of_force_f": "Bir pivottan r uzaklıkta, çubuğa θ açısıyla (yazılmazsa dik açı) iten bir F kuvvetinin döndürme etkisi; ya da bir yük ve pivottan uzaklığıyla dengelenmiş bir kaldıraç: başka bir uzaklıktaki kuvvet ve ne kadar kazanç sağladığı.",
