    "d_effort": "d kuvvet",
    "gravitation": "Kütle çekimi",
    "pull_between_two_masses": "Newton yasasıyla r uzaklıktaki iki kütle arasındaki çekim; ve ilki bir gezegen gibi, r'deki yerçekimi, dairesel bir yörüngenin hızı ve periyodu, kaçış hızı ve içinde kara delik olacağı yarıçap, Schwarzschild yarıçapı. Dünya 5.972e24 kg, yarıçapı 6.371e6 m; Güneş 1.989e30 kg.",
    "spring_of_stiffness_k": "Hooke yasasıyla x kadar gerilen ya da sıkıştırılan k sertlikli bir yay: kuvveti ve depoladığı enerji; bir kütleyle periyodu.",
    "drag_and_terminal_velocity": "Sürüklenme ve limit hız",
    "mass_falling_through_air": "Havada düşen bir kütle: sürüklenmenin ağırlığına eşit olduğu, daha hızlı düşemediği hız, bunun %95'ine ulaşmasının ne kadar sürdüğü ve o zamana kadar ne kadar düştüğü; ve bir hızdaki sürüklenme. Bir topun C<sub>d</sub>'si yaklaşık 0.47, düşen bir insanınki 1, bir arabanınki 0.3. Hava 1.225 kg/m³.",
    "cd": "Cd",
    "coulomb_s_law": "Coulomb yasası",
    "force_between_two_charges": "r uzaklıktaki iki yük arasındaki kuvvet, çekip itmedikleri, birincinin ikincinin yerindeki alanı ve potansiyeli, ve ikisinin enerjisi. Yükler 2µ veya 1.6e-19 gibi; k = 8.988 × 10⁹ N·m²/C².",
    "magnetic_force": "Manyetik kuvvet",
    "force_of_magnetic_field": "Bir B manyetik alanının içinden geçen bir yüke uyguladığı kuvvet, döndüğü çember, periyodu ve frekansı, yazılmazsa bir elektronunki; ya da akım taşıyan bir tele. Aralarındaki θ, yazılmazsa dik açı.",
