    "teslas": "tesla",
    "magnetic_field": "Manyetik alan",
    "field_of_current_at": "Bir akımın alanı: uzun düz bir telden r uzaklıkta, ve orada I₂ taşıyan ikinci bir tel için aralarındaki metre başına kuvvet; L boyunca N sarımlı, çekirdeği μ<sub>r</sub> kat güçlendiren bir solenoidin içinde; ya da r yarıçaplı ve N sarımlı bir halkanın ortasında. Dünyanınki yaklaşık 50 µT.",
    "solenoid": "Solenoid",
