    "induction": "İndüksiyon",
    "voltage_changing_field_makes": "Değişen bir alanın oluşturduğu gerilim, Faraday yasasıyla: N sarımlı ve A alanlı bir bobinde, alanı Δt'de ΔB değişirken; bir alanda v hızıyla hareket eden L uzunluğunda bir çubukta; ya da bobini dakikada belli devirle dönen bir jeneratörün tepe değeri. Bir dirençle akım.",
