    "type_two_of_speed": "Hız v, frekans f ve dalga boyu λ'dan ikisini yazın, üçüncüsü hesaplanır; periyot, açısal frekans ve dalga sayısı da.",
    "hz": "Hz",
    "standing_waves": "Duran dalgalar",
    "string_held_at_both": "Bir gitarınki gibi iki ucundan tutturulmuş, gerilmesi T ve metre başına kütlesi μ olan bir tel; ya da flüt veya klarnet gibi iki ucu açık ya da bir ucu kapalı bir boru: n. modunun frekansı, dalga boyu ve düğümleri, çizimli. 20 °C havada ses 343 m/s gider.",
