    "kg_m_2": "kg/m",
    "beats": "Vuruşlar",
    "two_notes_of_frequencies": "Frekansları birbirine yakın iki notanın birlikte çalınması: yükselip alçalan ses şiddeti, vuruşlar, saniyede kaç tane ve aralarındaki süre, ikisinin arasında duyulan nota ve sent cinsinden aralarındaki fark; çizimli. Bir tel diğerine akort edildikçe vuruşlar yavaşlar ve kaybolur.",
    "hz_440": "Hz, 440",
    "hz_444": "Hz, 444",
    "lenses_and_mirrors": "Mercekler ve aynalar",
    "thin_lens_or_mirror": "İnce bir mercek ya da ayna: odak uzaklığı f, cisme ve görüntüye uzaklıklardan ikisini yazın, üçüncüsü hesaplanır; büyütme ve görüntü. f yakınsak mercek veya çukur ayna için 0'dan büyük; 0'dan küçük görüntü uzaklığı sanaldır.",
    "lensmaker_s_equation": "Mercek yapımcısı denklemi",
    "thin_lens_of_index": "Kırılma indisi n, yüzey yarıçapları R<sub>1</sub>, ışığın önce karşılaştığı, ve R<sub>2</sub> olan ince bir mercek: odak uzaklığı, diyoptri cinsinden gücü ve ışığı toplayıp toplamadığı ya da dağıttığı; biçimi çizilir. Merkezi yüzeyin ötesindeyse yarıçap 0'dan büyüktür, yani iki yana şişkin bir mercekte R<sub>1</sub> 0'dan büyük, R<sub>2</sub> küçüktür; boşsa yüzey düzdür. Cam yaklaşık 1.5; suda n<sub>m</sub> 1.333.",
    "m_empty_flat": "m, boşsa düz",
    "refraction": "Kırılma",
    "light_going_from_one": "Snell yasasıyla bir ortamdan diğerine geçen ışık: normalden kırıldığı açı, kritik açı ve tamamen yansıyıp yansımadığı. Hava 1.000293, su 1.333, cam yaklaşık 1.5.",
    "interference": "Girişim",
    "light_through_two_slits": "d aralıklı iki yarıktan L uzaklıktaki bir ekrana düşen ışık: Young'a göre parlak saçaklarının arası; ya da milimetrede belli sayıda çizgisi olan bir kırınım ağından: her mertebenin açısı ve kaç tane olduğu. Kendi renginde çizilir.",
