    "one_slit_and_resolution": "Tek yarık ve çözünürlük",
    "light_through_one_slit": "a genişliğinde tek bir yarıktan geçen ışık: m. karanlık saçağın açısı, parlak ortanın genişliği ve L uzaklıktaki bir ekranda, metre olarak da. Ya da bir teleskop, kamera veya göz gibi D genişliğinde yuvarlak bir delikten: Rayleigh'e göre ayırt edebildiği iki nokta arasındaki en küçük açı ve bir uzaklıkta aralarının ne kadar olması gerektiği. Göz bebeği yaklaşık 2 ile 8 mm. Işık kendi renginde çizilir.",
