    "polarised_light_through_polariser": "Kendisine θ açılı bir polarizörden geçen kutuplanmış ışık: Malus yasasıyla geçen kısım, ve kutuplanmamış ışık için önce birinden geçerek; ve n₁'den n₂'ye bir yüzeyden yansıyan ışık için yansıyanın tamamen kutuplandığı açı, Brewster açısı.",
    "doppler_effect": "Doppler etkisi",
    "frequency_heard_of_source": "Hareket eden bir kaynağın hareket eden bir dinleyici tarafından duyulan frekansı: birbirine doğru hızlar 0'dan büyük, uzaklaşırken 0'dan küçük. 20 °C havada ses 343 m/s gider. Ya da v hızıyla uzaklaşan bir yıldız veya galaksinin ışığı, görelilikle: görülen dalga boyu, daha uzun, daha kırmızı, ve kırmızıya kayması z; 0'dan küçükse yaklaşıyor, daha mavi. Hidrojenin kırmızı çizgisi Hα 656.3 nm.",
