    "rise": "Yükselme",
    "reynolds_number": "Reynolds sayısı",
    "fluid_flowing_at_v": "d genişliğinde bir boruda v hızıyla akan bir akışkan: Reynolds sayısı ve katmanlar halinde düzgün mü (laminer) yoksa çalkantılı mı (türbülanslı) aktığı, borudaki hız profili çizilir; L uzunluğu boyunca sürtünmeyle kaybettiği basınç, Darcy-Weisbach ile, f borunun pürüzlülüğü ε'dan Colebrook denklemiyle, ve pompalama gücü. Yazılmazsa 20 °C'de su, 998 kg/m³ ve μ 1.002e-3 Pa·s; hava 1.204 ve 1.81e-5. Çelik boru yaklaşık 0.045 mm pürüzlü, plastik 0.0015.",
    "mm": "ε, mm",
