    "q_value": "Q değeri",
    "energy_nuclear_reaction_or": "Bir nükleer tepkimenin ya da bozunmanın açığa çıkardığı ya da soğurduğu enerji, önceki ve sonraki atomların u cinsinden kütlelerinden, aralarında + ile: 0'dan büyükse enerji açığa çıkar. Bir atom ikiye bozunurken enerjiyi nasıl paylaştıkları, hafif olan daha hızlı. Uranyum-238 238.050788 u, toryum-234 234.043601, helyum-4 4.002602, hidrojen-2 2.014102, hidrojen-3 3.016049, nötron 1.008665.",
