    "f_ma_inclined_plane": "F = ma, sürtünmeli eğik düzlem, makara üzerindeki kütleler, çarpışmalar, itme, kinetik ve potansiyel enerji, iş ve güç, tork ve kaldıraçlar, kütle çekimi ve Schwarzschild yarıçapı, yaylar, sürüklenme ve limit hız, Coulomb yasası, manyetik kuvvet, bir telin, bobinin ya da halkanın alanı, ve indüksiyon.",
    "electronics": "Elektronik",
    "resistor_colour_code_both": "İki yönde direnç renk kodu, SMD kodları ve EIA-96, seri ve paralel parçalar, Ohm yasası, bir telin direnci ve AWG'si, gerilim bölücü ve Thévenin, Wheatstone köprüsü, LED dirençleri, kondansatörler, RC ve RL, birinci ve ikinci dereceden filtreler, paralel plakalar, transformatörler ve AC, üç fazlı güç, R, L ve C'nin empedansı ve rezonansı, elektrik maliyeti, pil ömrü; diyotlar ve doğrultucular dalgalanmalarıyla; anahtarlayan ve kutuplanan transistörler, MOSFET'ler, Zener'ler, LM317, op-amp'ler ve 555; dBm, dBV ve dBµV, ve dB cinsinden kazançlar. Bir parçanın değeri yazıldığı gibi: 4.7k, 4k7, 100n; satın alınacak bir direnç, E12'den.",
    "v_f_standing_waves": "v = fλ, tellerin ve boruların duran dalgaları, vuruşlar, mercekler ve aynalar, mercek yapımcısı denklemi, kırılma ve kritik açı, iki yarıktan ya da bir kırınım ağından girişim, tek yarık ve bir merceğin çözünürlüğü, kutuplanma, sesin ve ışığın Doppler etkisi, ışık ve fotonlar, ve desibel cinsinden ses.",
    "matter": "Madde",
    "heat_q_mc_t": "Isı: herhangi üçünden Q = mcΔT, gizli ısı, karışım, ısıl genleşme, iletim, ışınım, Newton'un soğuma yasası, çiy noktası, gaz moleküllerinin hızları, izotermal, izobarik, izokorik ya da adyabatik bir ideal gaz, ve ısı makineleri. Katılar: gerilme ve şekil değiştirme. Akışkanlar: yoğunluk, basınç, bir derinlikteki basınç, kaldırma kuvveti, bir borudaki akış, borunun sürtünmesiyle Reynolds sayısı, ve Stokes yasası.",
    "modern": "Modern",
    "e_mc_binding_energy": "E = mc², bağlanma enerjisi, bir tepkimenin Q-değeri, fotoelektrik etki, de Broglie dalga boyları, belirsizlik ilkesi, kutudaki parçacık, Compton saçılması, tünelleme, özel görelilik, hidrojenin çizgileri ve Bohr yörüngeleri, ve radyoaktif bozunma.",
    "biology": "Biyoloji",
    "genetics_from_punnett_squares": "Punnett karelerinden gen haritalarına ve genetik riske genetik; DNA ve RNA, çevrilmiş, hizalanmış, primerler, CRISPR kılavuzları ve jellerle; proteinler ve enzimler; laboratuvarın seyreltmeleri, sayımları ve qPCR'ı; hücreler; sağlık; ve ekoloji ve evrim. Koymak için bir sayıya tıklayın.",
    "close_biology": "Biyolojiyi kapat",
    "genetics": "Genetik",
    "punnett_squares_of_up": "Altı gene kadar Punnett kareleri, çizilmiş, ve X'in; Hardy–Weinberg, p'den, χ² testiyle sayımlardan, ya da çekinik özellikten; bir çaprazlamanın χ²'si; iki ya da üç genin gen haritaları, kromozom çizilmiş; yavruların olasılıkları; kalıtsallık, ıslahçı denklemine göre; epistazi ve hangi oranın uyduğu; genetik risk, aile soy ağacı olarak çizilmiş; ve kan grupları.",
    "sequence_s_length_bases": "Bir dizinin uzunluğu, bazları, boyunca GC'si ve kütlesi, tümleyeni ve ters tümleyeniyle; altı çerçevede çeviri ve açık okuma çerçeveleri, çizilmiş; kodon çarkı; en yakın komşulara göre primer T<sub>m</sub>'si, erimeleri çizilmiş; A<sub>260</sub>'a göre DNA ve RNA ve saflıkları; kütle, mol ve kopyalar; ligasyon, plazmit çizilmiş; jelde yürütülen restriksiyon kesimleri; PCR'ın kopyaları, döngü döngü; global ve lokal hizalamalar, nokta grafiğiyle; CRISPR kılavuzları; IUPAC kodlarından motifler; mutagenez ve Gibson montajı için primerler; ve genomlar ve kopyaları.",
    "protein_s_mass_pi": "Bir proteinin kütlesi, pI'sı, yükü, sönümü ve hidropatisi, çizilmiş; yirmi amino asit, her birinin titrasyonu çizilmiş; A<sub>280</sub>'e ya da bir standart eğriye göre protein derişimi; V<sub>max</sub> ve K<sub>m</sub>'den ya da noktalara uydurulmuş enzim kinetiği, inhibitörler ve Lineweaver–Burk grafiğiyle; Hill'e göre bağlanma; doz–yanıt, IC<sub>50</sub>'si uydurulmuş; ve bir saflaştırma tablosu.",
    "lab": "Laboratuvar",
    "c_v_c_v": "C₁V₁ = C₂V₂ ve seri seyreltmeler, tüpleri çizilmiş; molaritesinden, formülünden, yüzdesinden ya da bir stoktan çözelti hazırlama; hücre sayımı; büyüme ve ikiye katlanma, ve OD<sub>600</sub>; koloniler ve CFU/mL; santrifüjün RPM'i ve g'si; bir PCR ana karışımı; ΔΔCt'ye ve standart eğrisine göre qPCR; hata çubuklarıyla ortalama ± 2 SE; kromatografinin R<sub>f</sub>'si; mikroskop; bir jelden boylar; transformasyon verimi; plakalara ekim; MOI; radyoizotoplar; ve tamponlar.",
    "water_potential_osmolarity_and": "Su potansiyeli, osmolarite ve tonisite, bir alyuvar çizilmiş; yüzey alanı / hacim; Q₁₀; Fick'e göre difüzyon; Nernst ve Goldman'a göre zar potansiyelleri; serbest enerji; kalbin debisi ve kan basıncı, çizilmiş; ve solunum, ATP'si ve solunum katsayısı.",
    "health": "Sağlık",
    "diagnostic_tests_their_sensitivity": "Tanı testleri, duyarlılıkları, özgüllükleri ve öngörü değerleri, bin kişi çizilmiş; aralıklarıyla risk ve odds oranları, ve tedavi için gereken sayı; SIR'a göre bir salgın ve sürü bağışıklığı; oksijen ve hemoglobin, Bohr kayması çizilmiş; Hodgkin ve Huxley'e göre bir aksiyon potansiyeli; böbrekler, eGFR ve klerens; VKİ ve enerji; ve bir ilacın dozları boyunca düzeyleri. Öğrenmek için, bakım için değil.",
