    "again_to_return_buttons": "yeniden tıklayın.",
    "opens_parenthetical_expression_expressions": "[(] Parantezli bir ifade açar. İfadeler iç içe olabilir. Ona tıklamak, parantezli bir ifadenin hâlâ etkin olduğunu bildirmek için düğmenin çevresinde bir halka belirtir (tüm ifadeler kapanış parantezi ya da eşittir işaretiyle kapanana kadar).",
    "number_right_before_parenthesis": "Parantezin hemen önündeki bir sayı çarpılır: 5 ( 2 + 3 ), 5 × (2 + 3)'tür.",
    "closes_parenthetical_expression_ring": "[)] Parantezli bir ifadeyi kapatır. ( parantez tuşunun çevresindeki halka, tüm ifadeler bu tuşla kapanana ya da eşittir işaretine tıklanana kadar kalır.",
    "calculates_percentages_adds_markups": "[%] Yüzdeleri hesaplar, kâr ekler ve indirim düşer. Tek başına değeri 100'e böler: 50 %, 0.5 verir. Örneğin 500'ün %8'ini hesaplamak için 8 % × 500 = girin, 40 verir.",
    "to_add_markup_or": "Kâr eklemek ya da indirim düşmek için onu + ya da – tuşundan sonra kullanın. Örneğin %8 satış vergili 500 $'lık bir ürünün toplam maliyetini hesaplamak için 500 + 8 % = girin, 540 verir.",
