    "shift_w_operator_multiplies": "[Shift+W] O an gösterilen değeri, gireceğiniz sonraki değerin 10 kuvvetiyle çarpan bir işleç.",
    "enters_last_result_so": "[a] Son sonucu, yeni bir denklemin herhangi bir yerinde kullanılabilmesi için girer: 5 ×",
