    "h_n_returns_random": "[h, n] 0 ile 1 arasında rastgele bir sayı verir.",
    "v_click_to_clear": "[v] Belleği temizlemek için tıklayın.",
    "b_click_to_add": "[b] Gösterilen sayıyı bellekteki sayıya eklemek için tıklayın. Bellekte sayı yoksa, gösterilen sayıyı belleğe kaydetmek için tıklayın. Ekran bir an M+ gösterir.",
    "n_click_to_subtract": "[n] Gösterilen sayıyı bellekteki sayıdan çıkarmak için tıklayın. Bellekte sayı yoksa, gösterilen sayıyı sıfırdan çıkarılmış olarak belleğe kaydetmek için tıklayın. Ekran bir an M– gösterir.",
    "m_click_to_replace": "[m] Gösterilen sayıyı bellekteki sayıyla değiştirmek için tıklayın.",
    "m_on_display_shows": "Ekrandaki M, bellekte bir sayı kayıtlı olduğunu gösterir. Kayıtlı sayı sıfır olursa M de kaybolur.",
    "shift_n_combinations_ways": "[Shift+N] Kombinasyonlar: n şeyden r tanesini seçme yolları. Örneğin 10 nCr 3 = 120 verir. × ve ÷'den önce, kuvvetlerden sonra hesaplanır.",
    "shift_p_permutations_ways": "[Shift+P] Permütasyonlar: n şeyden r tanesini sıralı dizme yolları. Örneğin 5 nPr 2 = 20 verir.",
    "shift_m_on": "[Shift+M] Şurada:",
    "remainder_after_dividing_17": ". Bölmeden sonra kalan: 17 mod 5 = 2. İkinci sayının işaretini alır (-7 mod 3 = 2), ve ondalıklarla çalışır (7.5 mod 2 = 1.5).",
